import sys

def maximumMatch(G):
    if not G:
        return 0
    M = len(G)
    N = len(G[0]) if M > 0 else 0

    match = [-1] * N

    def dfs(u, visited):
        for v in range(N):
            if G[u][v] == 1 and not visited[v]:
                visited[v] = True
                if match[v] < 0 or dfs(match[v], visited):
                    match[v] = u
                    return True
        return False

    result = 0
    for u in range(M):
        visited = [False] * N
        if dfs(u, visited):
            result += 1

    return result

def main():
    input_data = sys.stdin.read().strip()
    if not input_data:
        return

    lines = input_data.split('\n')
    matrix_lines = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line.startswith('{') or line.startswith('['):
            line = line.replace('{', '[').replace('}', ']').replace(' ', '')
        if ',' in line:
            parts = line.split(',')
            row = []
            for p in parts:
                p = p.strip().strip('[]{}')
                if p:
                    row.append(int(p))
            if row:
                matrix_lines.append(row)

    G = matrix_lines
    print(maximumMatch(G))

if __name__ == "__main__":
    main()
